/**
 * Captured-journal replay test (issue #2908, AC5; PR #3284 hardening).
 *
 * Provenance (PRR-043/PRR-044): tests/fixtures/background-delegations-2908.jsonl
 * is a sanitized capture of a REAL review run's delegation ledger (36 swarm-pr-*
 * lanes plus one blocking record; captured 2026-09-09 from a live plugin
 * checkout's .swarm/background-delegations.jsonl). The fixture is generated by
 * the committed, deterministic, idempotent scrub
 * scripts/scrub-delegation-fixture-2908.mjs (see its header for the exact rule
 * set). FIXTURE_PROVENANCE below pins the fixture's own sha256 and the scrub
 * script's sha256, so a silent re-baselining of the fixture — or an unnoticed
 * edit to the scrub — fails the pin test. A deliberate re-baseline must update
 * the pins AND re-derive EXPECTED_TERMINALS from the new capture consciously.
 *
 * Sanitization rules, exactly as the scrub executes them: (1) every
 * prose-bearing string in results and receipts (result text/error, finding
 * title/body/evidence, non-local location label/detail, attestation
 * coverageScope/evidence, unresolved detail) and workspace.scope is replaced by
 * a length-preserving '[sanitized]---' placeholder; (2) workspace.directory is
 * redacted to '<redacted>'; (3) structured JUDGMENT fields are neutralized
 * (PRR-020): finding severity -> 'LOW', riskImpact -> 'ORDINARY', riskTags ->
 * [], location line/endLine/column/endColumn dropped, envelope.outcome
 * re-derived from the retained envelope structure, terminalErrorClass reduced
 * to its schema-required kind enum plus a constant category; (4) receipt-level
 * workflow-lane references are renamed per record to sanitized-lane-<k>
 * (injective, preserving every receipt partition invariant); (5) derived
 * digests are recomputed over the sanitized bytes so the fixture validates as a
 * real ledger row set: result.digest, the outputRef third component (sha256 of
 * the SANITIZED text — it previously held the sha256 of the raw prose and was a
 * byte-exactness oracle over the redacted content, PRR-019),
 * semanticEnvelopeDigest, and terminalResult.eventId per the production
 * buildBackgroundCompletionEventId derivation (PRR-022).
 *
 * Deliberately PRESERVED verbatim (enumerated per PRR-020): structured identity
 * (ids — correlationId/jobId/session ids/callID/batchId/laneId — statuses,
 * mode, timestamps, prompt/git sha fields, numeric counters), record-level
 * workflowLane/ownedWorkflowLanes, workflowLaneFailureClass (closed schema
 * enum), finding location.file repo-relative paths, location.kind and
 * terminalErrorClass.kind (schema-required enum values), and the envelope's
 * retained findings/attestations/unresolved structure. None of those preserved
 * fields are load-bearing for these assertions — the tests below assert
 * status/terminalResult/eventId/digest identities/counts only.
 *
 * The EXPECTED_TERMINALS table is derived from the PRE-sanitization raw capture
 * (folded at authoring time), NOT recomputed from the fixture, so a fold defect
 * cannot satisfy this test circularly.
 *
 * Checkpoint coverage: the compaction test force-compacts a copy through the
 * real compaction (issue #2034) and requires the checkpoint+tail fold to equal
 * the legacy-ledger fold. The supersession test derives a NEWER
 * same-correlationId snapshot line and asserts the fold keeps the newest
 * terminal (PRR-038) — the shipped fixture has unique correlationIds, so its
 * legacy fold alone exercises no multi-snapshot supersession.
 */

import { afterEach, describe, expect, test } from 'bun:test';
import { createHash } from 'node:crypto';
import * as fs from 'node:fs';
import * as path from 'node:path';
import {
	BACKGROUND_DELEGATIONS_CHECKPOINT_FILE,
	BACKGROUND_DELEGATIONS_FILE,
	buildBackgroundCompletionEventId,
	compactBackgroundDelegations,
	readDelegationsDetailed,
} from '../../../src/background/pending-delegations.js';
import { prReviewLaneResultEnvelopeDigest } from '../../../src/background/pr-review-contract.js';
import { canonicalMkdtemp } from '../../helpers/tmpdir.js';

const FIXTURE = path.join(
	import.meta.dir,
	'..',
	'..',
	'fixtures',
	'background-delegations-2908.jsonl',
);

const SCRUB_SCRIPT = path.join(
	import.meta.dir,
	'..',
	'..',
	'..',
	'scripts',
	'scrub-delegation-fixture-2908.mjs',
);

/**
 * In-band provenance for the JSONL fixture (a .jsonl file must stay parseable
 * line-per-record, so unlike the telemetry golden JSON it cannot carry a
 * $comment line; the pin lives here instead). The scrub commit is identified
 * by the pinned scrub-script digest, which serves the same audit function.
 */
const FIXTURE_PROVENANCE = {
	capturedFrom: 'live plugin checkout .swarm/background-delegations.jsonl',
	capturedOn: '2026-09-09',
	sourceShape: '37 records: 36 swarm-pr-* lanes plus 1 blocking record',
	scrubScript: 'scripts/scrub-delegation-fixture-2908.mjs',
	scrubScriptSha256:
		'298827b1c8cc8db26e404e84858f3df83d676b2cbc85d5ebd1bf2254cf11f782',
	fixtureSha256:
		'0a60b00ed88fff1e5f369228258feb0f4b63e1c0d531c8f5ccabc5de768c2ee8',
} as const;

/** Records carrying a receipt on BOTH result copies (23 records x 2 copies). */
const RECEIPT_RECORD_COUNT = 23;
const RECEIPT_COPY_COUNT = 46;

/** [correlationId, folded status] pairs from the pre-sanitization live fold. */
const EXPECTED_TERMINALS: ReadonlyArray<readonly [string, string]> = [
	['generic-session', 'completed'],
	['ses_f780661b8ffeKVytukSMmXiUjK', 'completed'],
	['ses_f78223af1ffezqL2yjztcFR25t', 'error'],
	['ses_f7822a1adffer5PC5gpMMdQs1h', 'error'],
	['ses_f7828c298ffeCZ0HEFvtQbOfyC', 'completed'],
	['ses_f782d77e9ffe0R7RKIplZxYkz6', 'completed'],
	['ses_f78343dfeffeikKu9HThId8FKY', 'error'],
	['ses_f783ab7e7ffegy2Ixw28ubS3Uo', 'error'],
	['ses_f783e0c4affekfenWq0og39s23', 'error'],
	['ses_f7859e908fferd9vSSa4cCRY4x', 'error'],
	['ses_f7859e90affeZowf2esfRouJyd', 'completed'],
	['ses_f7859e90dffefmWre31WpSbKBu', 'completed'],
	['ses_f78731cbbffeuR7HrtmGDf4RWW', 'completed'],
	['ses_f78731cbfffex6S65hq3PdJ3ya', 'completed'],
	['ses_f788217ebffeJUQWUVmw5fP2Tn', 'completed'],
	['ses_f788479edffeFk8UPNQ0ie1tmS', 'error'],
	['ses_f78885dd9ffemRib9saAZ5o4no', 'completed'],
	['ses_f788c4161ffeHSSQPt3nkD773h', 'error'],
	['ses_f789013b0ffev462iSMRfkkuOz', 'completed'],
	['ses_f78929f79ffeR1u8qTedtdGzeD', 'error'],
	['ses_f7896a2a7ffeC5S0t2HhWLMbMI', 'completed'],
	['ses_f7896a2aeffeYV63aYBLgJBfBO', 'completed'],
	['ses_f789ae3abffesAONwyE0C9fyMQ', 'error'],
	['ses_f789ae3aeffeG63zA3btvYUb37', 'error'],
	['ses_f78b34075ffer0O471luHxyvHV', 'completed'],
	['ses_f78b34078ffe4KHAz6XSFyK7M2', 'completed'],
	['ses_f78b93013ffe4wBKGXQhS9sgVh', 'error'],
	['ses_f78be3278ffekF8OT17dazzX71', 'error'],
	['ses_f78c3e8dfffeel3lHxw2vDY23g', 'error'],
	['ses_f78c3e8e3ffe06u0Onlf9Fu0SJ', 'completed'],
	['ses_f78c3e8ebffe1RDqFMumz0WlMO', 'completed'],
	['ses_f78cbaa07ffeCni8764CoN8ixj', 'completed'],
	['ses_f78cbaa0cffeKWwQ9PVGyh81Ta', 'completed'],
	['ses_f791276daffeY2h44zfevcPrXb', 'error'],
	['ses_f791797faffeqcENn64x4yvok8', 'error'],
	['ses_f791b2301ffexhI5LU8EUL33G2', 'error'],
	['ses_f79203fa0ffeiX438JTq3eJgSL', 'error'],
];

const sha256Hex = (value: string): string =>
	createHash('sha256').update(value).digest('hex');

const sha256File = (file: string): string =>
	createHash('sha256').update(fs.readFileSync(file)).digest('hex');

const RM_SYNC_ATTEMPTS = 4;
const RM_SYNC_RETRY_WAIT_MS = 25;

const sleepSync = (ms: number): void => {
	Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
};

/**
 * Windows can briefly hold directory handles (EBUSY/EPERM) after a test body
 * finishes. Retry the removal a bounded number of times with a short
 * synchronous wait, then ASSERT the directory is gone — a temp-store leak is a
 * failure to surface, not environmental noise to swallow.
 */
const removeTreeWithRetry = (dir: string): void => {
	let lastError: unknown;
	for (let attempt = 1; attempt <= RM_SYNC_ATTEMPTS; attempt++) {
		try {
			fs.rmSync(dir, { recursive: true, force: true });
			lastError = undefined;
			break;
		} catch (error) {
			lastError = error;
			sleepSync(RM_SYNC_RETRY_WAIT_MS);
		}
	}
	if (lastError !== undefined) throw lastError;
	expect(fs.existsSync(dir), `temp store must be removed: ${dir}`).toBe(false);
};

describe('captured-journal replay (issue #2908)', () => {
	const dirs: string[] = [];

	const seedStore = (): string => {
		const dir = canonicalMkdtemp('delegation-replay-2908-');
		dirs.push(dir);
		fs.mkdirSync(path.join(dir, '.git'), { recursive: true });
		fs.mkdirSync(path.join(dir, '.swarm'), { recursive: true });
		fs.copyFileSync(
			FIXTURE,
			path.join(dir, '.swarm', BACKGROUND_DELEGATIONS_FILE),
		);
		return dir;
	};

	afterEach(() => {
		for (const dir of dirs.splice(0)) {
			removeTreeWithRetry(dir);
		}
	});

	test('fixture provenance is pinned (PRR-043/PRR-044)', () => {
		const raw = fs.readFileSync(FIXTURE, 'utf-8');
		expect(raw.endsWith('\n'), 'fixture must be newline-terminated').toBe(true);
		expect(raw.split('\n').length - 1).toBe(EXPECTED_TERMINALS.length);
		expect(sha256File(FIXTURE)).toBe(FIXTURE_PROVENANCE.fixtureSha256);
		expect(fs.existsSync(SCRUB_SCRIPT), 'committed scrub script').toBe(true);
		expect(sha256File(SCRUB_SCRIPT)).toBe(FIXTURE_PROVENANCE.scrubScriptSha256);
	});

	test('legacy-ledger fold equals the recorded live terminal set', () => {
		const dir = seedStore();
		const outcome = readDelegationsDetailed(dir);
		expect(outcome.status).toBe('ok');
		if (outcome.status !== 'ok') return;
		// Record-count guard: the lenient reader must not have skipped any line.
		expect(outcome.records.length).toBe(EXPECTED_TERMINALS.length);
		const folded = new Map(
			outcome.records.map((record) => [record.correlationId, record]),
		);
		expect(folded.size).toBe(EXPECTED_TERMINALS.length);
		const completed = EXPECTED_TERMINALS.filter(
			([, status]) => status === 'completed',
		).length;
		const errors = EXPECTED_TERMINALS.filter(
			([, status]) => status === 'error',
		).length;
		expect(completed).toBe(19);
		expect(errors).toBe(18);
		for (const [correlationId, status] of EXPECTED_TERMINALS) {
			const record = folded.get(correlationId);
			expect(
				record,
				`missing folded record for ${correlationId}`,
			).toBeDefined();
			if (!record) continue;
			expect(record.status, correlationId).toBe(status);
			expect(record.terminalResult?.status, correlationId).toBe(status);
			expect(record.completedAt, correlationId).toBeGreaterThan(0);
		}
	});

	test('sanitized records satisfy the production digest and event-id invariants (PRR-019/PRR-022)', () => {
		const dir = seedStore();
		const outcome = readDelegationsDetailed(dir);
		expect(outcome.status).toBe('ok');
		if (outcome.status !== 'ok') return;
		let receiptCopies = 0;
		let recordsWithReceipt = 0;
		for (const record of outcome.records) {
			const terminal = record.terminalResult;
			expect(terminal, `${record.correlationId} terminalResult`).toBeDefined();
			if (!terminal) continue;
			// (a) eventId is exactly the production-derived completion id for
			// THIS record's [correlationId, jobId, status, digest] material.
			expect(terminal.eventId, `${record.correlationId} eventId`).toBe(
				buildBackgroundCompletionEventId({
					correlationId: record.correlationId,
					jobId: record.jobId,
					status: terminal.status,
					resultDigest: terminal.result.digest,
				}),
			);
			let sawReceipt = false;
			for (const container of [record.result, terminal.result]) {
				if (!container) continue;
				// PRR-019: the outputRef third component must be the digest of
				// the SANITIZED text (equal to result.digest), never a
				// byte-exactness oracle over the raw redacted prose.
				if (typeof container.outputRef === 'string') {
					const parts = container.outputRef.split(':');
					expect(parts, `${record.correlationId} outputRef shape`).toHaveLength(
						4,
					);
					expect(parts[0]).toBe('L1');
					expect(parts[3], `${record.correlationId} outputRef digest`).toBe(
						container.digest,
					);
				}
				if (typeof container.text === 'string') {
					expect(
						sha256Hex(container.text),
						`${record.correlationId} text digest`,
					).toBe(container.digest);
				}
				const receipt = container.prReviewResultReceipt;
				if (!receipt) continue;
				sawReceipt = true;
				receiptCopies += 1;
				// (b) every receipt's semanticEnvelopeDigest equals the canonical
				// production envelope digest over the SANITIZED envelope.
				expect(
					receipt.semanticEnvelopeDigest,
					`${record.correlationId} semanticEnvelopeDigest`,
				).toBe(prReviewLaneResultEnvelopeDigest(receipt.envelope));
			}
			if (sawReceipt) recordsWithReceipt += 1;
		}
		expect(recordsWithReceipt).toBe(RECEIPT_RECORD_COUNT);
		expect(receiptCopies).toBe(RECEIPT_COPY_COUNT);
	});

	test('checkpoint+tail fold after real compaction equals the legacy fold', async () => {
		const dir = seedStore();
		const legacy = readDelegationsDetailed(dir);
		expect(legacy.status).toBe('ok');
		if (legacy.status !== 'ok') return;
		const compact = await compactBackgroundDelegations(dir, { force: true });
		expect(compact.status).not.toBe('skipped');
		expect(
			fs.existsSync(
				path.join(dir, '.swarm', BACKGROUND_DELEGATIONS_CHECKPOINT_FILE),
			),
			'compaction must publish a checkpoint',
		).toBe(true);
		const refolded = readDelegationsDetailed(dir);
		expect(refolded.status).toBe('ok');
		if (refolded.status !== 'ok') return;
		expect(refolded.records.length).toBe(legacy.records.length);
		const byId = new Map(legacy.records.map((r) => [r.correlationId, r]));
		for (const record of refolded.records) {
			const before = byId.get(record.correlationId);
			expect(before, record.correlationId).toBeDefined();
			if (!before) continue;
			expect(record.status).toBe(before.status);
			expect(record.terminalResult?.status).toBe(before.terminalResult?.status);
			expect(record.terminalResult?.eventId).toBe(
				before.terminalResult?.eventId,
			);
			expect(record.completedAt).toBe(before.completedAt);
		}
	});

	test('a newer same-id snapshot supersedes the older terminal in the fold (PRR-038)', () => {
		const dir = seedStore();
		const before = readDelegationsDetailed(dir);
		expect(before.status).toBe('ok');
		if (before.status !== 'ok') return;
		const target = before.records.find(
			(record) => record.correlationId === 'generic-session',
		);
		expect(target, 'supersession target record').toBeDefined();
		if (!target?.terminalResult) return;
		const priorTerminal = target.terminalResult;
		const flipped: 'completed' | 'error' =
			target.status === 'completed' ? 'error' : 'completed';
		const laterRecordedAt = target.completedAt + 5000;
		const supersedingEventId = buildBackgroundCompletionEventId({
			correlationId: target.correlationId,
			jobId: target.jobId,
			status: flipped,
			resultDigest: priorTerminal.result.digest,
		});
		const superseding = {
			...target,
			status: flipped,
			updatedAt: target.updatedAt + 5000,
			completedAt: laterRecordedAt,
			terminalResult: {
				eventId: supersedingEventId,
				status: flipped,
				recordedAt: laterRecordedAt,
				result: priorTerminal.result,
			},
		};
		fs.appendFileSync(
			path.join(dir, '.swarm', BACKGROUND_DELEGATIONS_FILE),
			`${JSON.stringify(superseding)}\n`,
		);
		const after = readDelegationsDetailed(dir);
		expect(after.status).toBe('ok');
		if (after.status !== 'ok') return;
		expect(after.records).toHaveLength(before.records.length);
		const folded = after.records.find(
			(record) => record.correlationId === 'generic-session',
		);
		expect(folded, 'superseded fold entry').toBeDefined();
		if (!folded) return;
		expect(folded.status).toBe(flipped);
		expect(folded.terminalResult?.status).toBe(flipped);
		expect(folded.terminalResult?.eventId).toBe(supersedingEventId);
		expect(folded.completedAt).toBe(laterRecordedAt);
		// No collateral fold damage: every other record keeps its prior terminal.
		const beforeById = new Map(
			before.records.map((record) => [record.correlationId, record]),
		);
		for (const record of after.records) {
			if (record.correlationId === target.correlationId) continue;
			const prior = beforeById.get(record.correlationId);
			expect(prior, record.correlationId).toBeDefined();
			if (!prior) continue;
			expect(record.status, record.correlationId).toBe(prior.status);
			expect(record.terminalResult?.eventId, record.correlationId).toBe(
				prior.terminalResult?.eventId,
			);
		}
	});
});
